#!/usr/bin/env node
/**
 * Raster pyramid — visible-tile generation cost model (2026-08-09).
 *
 * Compares the two raster paths for large layers viewed at low zoom:
 *
 *   retained full-surface  — one full-layer intermediate built from every
 *                            tile, then one drawImage (the 2026-08-03 model;
 *                            see bench-raster-reconstruction.mjs).
 *   spatial tiled LOD      — the visible tiles at the LOD level that matches
 *                            the zoom, each generated by a real
 *                            premultiplied-alpha box downsample (imported
 *                            from @varve/engine via tsx), plus drawImage per
 *                            tile.
 *
 * The pyramid arm's typed-array traffic is REAL (imports the shipped
 * downsample code); the draw-image count is modeled. The retained arm is the
 * existing lower-bound model — so the comparison understates the pyramid's
 * advantage, exactly like the 2026-08-03 record.
 *
 * Usage: npx tsx scripts/perf/bench-raster-pyramid-tiles.mjs
 */
import { performance } from 'node:perf_hooks';
import { downsampleParentTile } from '../../packages/engine/src/rasterPyramid/downsample.ts';

const TILE = 128;
const WARMUP = 3;
const ITERS = 12;

// --- retained full-surface model (mirror of bench-raster-reconstruction) ---
function rebuildAll(cols, rows) {
  const width = cols * TILE;
  const height = rows * TILE;
  const t0 = performance.now();
  const surface = new Uint8ClampedArray(width * height * 4);
  const t1 = performance.now();
  for (let col = 0; col < cols; col++) {
    for (let row = 0; row < rows; row++) {
      const pixels = new Uint8ClampedArray(TILE * TILE * 4);
      const imageData = new Uint8ClampedArray(TILE * TILE * 4);
      imageData.set(pixels);
      surface.set(imageData, (row * cols + col) * TILE * TILE * 4);
    }
  }
  const t2 = performance.now();
  return { alloc: t1 - t0, tiles: t2 - t1, total: t2 - t0 };
}

// --- pyramid arm: real generation of one visible tile ---
function makeChild(color) {
  const px = new Uint8ClampedArray(TILE * TILE * 4);
  for (let i = 0; i < px.length; i += 4) {
    px[i] = color;
    px[i + 1] = color;
    px[i + 2] = color;
    px[i + 3] = 255;
  }
  return px;
}

function makeSourceTiles(cols, rows) {
  const tiles = new Map();
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      tiles.set(`${c}:${r}`, makeChild((c * 40 + r * 13) % 256));
    }
  }
  return tiles;
}

function generateVisibleTiles(layerSize, level, childCols, sourceTiles) {
  // Visible tiles at the LOD: one level tile per 128 device px at DPR 1.
  const visibleCols = Math.max(1, Math.ceil(layerSize / (TILE * 2 ** level)));
  const t0 = performance.now();
  const tileSize = 128;
  let generated = 0;
  for (let c = 0; c < visibleCols; c++) {
    for (let r = 0; r < visibleCols; r++) {
      const children = [];
      for (let dy = 0; dy < 2; dy++) {
        for (let dx = 0; dx < 2; dx++) {
          const cc = c * 2 + dx;
          const rr = r * 2 + dy;
          children.push({
            coord: { col: cc, row: rr },
            pixels: sourceTiles.get(`${cc}:${rr}`),
          });
        }
      }
      downsampleParentTile({
        childLevel: { width: childCols * tileSize, height: childCols * tileSize },
        children,
        parent: { col: c, row: r },
        tileSize,
      });
      generated++;
    }
  }
  const total = performance.now() - t0;
  return { generated, total };
}

function bench(fn, label) {
  for (let i = 0; i < WARMUP; i++) fn();
  const samples = [];
  for (let i = 0; i < ITERS; i++) {
    const s = fn();
    samples.push(s.total ?? s);
  }
  samples.sort((a, b) => a - b);
  const p50 = samples[Math.floor(samples.length / 2)];
  const p95 = samples[Math.floor(samples.length * 0.95)];
  return { label, p50, p95 };
}

const sizes = [2048, 4096, 8192];
const zooms = [0.125, 0.0625, 0.01];

console.log('Layer   Zoom     Retained p50/p95      Pyramid p50/p95       ratio');
for (const size of sizes) {
  const cols = size / TILE;
  const sourceTiles = makeSourceTiles(cols, cols);
  for (const zoom of zooms) {
    const level = Math.max(0, Math.min(14, Math.round(-Math.log2(zoom))));
    const retained = bench(() => rebuildAll(cols, cols), 'retained');
    const pyramid = bench(() => generateVisibleTiles(size, level, cols, sourceTiles), 'pyramid');
    const ratio = retained.p50 / Math.max(0.0001, pyramid.p50);
    console.log(
      `${size}    ${(zoom * 100).toFixed(1).padStart(5)}%   ${retained.p50.toFixed(2).padStart(8)} / ${retained.p95.toFixed(2).padStart(8)} ms   ${pyramid.p50.toFixed(2).padStart(8)} / ${pyramid.p95.toFixed(2).padStart(8)} ms   ${ratio.toFixed(1)}x`,
    );
  }
}
